def is_power_of_two(n):
    return n > 0 and (n & (n - 1) == 0)

solutions = []
x_start = 8
x_end = 50
step = 3  # Since x = 2 (mod 3)

print("Starting search for n=3, x > 5, x = 2 (mod 3)")
print("--------------------------------------------------")

for x in range(x_start, x_end, step):
    # Equation: x^3 + x - 2 = 2^k
    LHS = x**3 + x - 2

    if is_power_of_two(LHS):
        k = LHS.bit_length() - 1
        solutions.append((x, 3, k))
        print(f"Solution found: x={x}. LHS = {LHS} = 2^{k}. Tuple: ({x}, 3, {k})")
    # else:
    #     print(f"x={x}: LHS = {LHS} (Not a power of 2)")

if not solutions:
    print("\nNo solutions found in the tested range.")
else:
    print("\nSummary of solutions found:")
    for sol in solutions:
        print(sol)
